// 真实教师课时只结一次；已教费用不退，任何取消/死亡只释放本原Action的未教预约。
#include "resident/kernel/common_action_occupation.hpp"
#include "growth_tactic_lesson_rules.hpp"
#include <algorithm>
namespace hanmo::resident {namespace {
template<class T>Outcome<T> fail(const Status& s){return {false,{},s.error};}
Integer periods(const GrowthTacticLessonState& state,const StableId& id){Integer n=0;for(const auto& row:state.credits.rows())if(row.second.started_fact_id==id)++n;return n;}
std::size_t position(const CommonStore& c,const StableId& id){const auto& order=c.state().facts.order();return std::find(order.begin(),order.end(),id)-order.begin();}
Outcome<const GrowthTacticLessonStart*> active(const CommonStore& c,const GrowthTacticLessonState& state,const StableId& id){auto valid=validate_growth_tactic_lesson_shape(state);if(!valid.ok)return fail<const GrowthTacticLessonStart*>(valid);const auto* s=state.starts.find(id);const auto* header=c.state().facts.find(id);if(!s||!header||header->id!=id||header->kind!=s->kind||header->domain!="growth_tactic_lessons")return fail<const GrowthTacticLessonStart*>(common_failure("TacticLessonActualStartRequired",id));for(const auto& row:state.closures.rows())if(row.second.started_fact_id==id)return fail<const GrowthTacticLessonStart*>(common_failure("TacticLessonAlreadyClosed",id));const auto* a=c.action(s->action_id);if(!a||a->kind!="tactic_lesson"||a->actor_id!=s->agreement.student_id||a->participants!=std::vector<StableId>{s->agreement.student_id,s->agreement.teacher_id}||a->start_tick!=s->agreement.tick)return fail<const GrowthTacticLessonStart*>(common_failure("TacticLessonActionMismatch",id));return {true,s,{}};}
// 未知available/location变化不产生自证原因；在场源必须仍是本Action真实双方。
Status present(const CommonStore& c,const GrowthTacticLessonStart& start){for(const auto* id:{&start.agreement.student_id,&start.agreement.teacher_id}){const auto* actor=c.actor(*id);if(!actor||!actor->alive||!actor->available||actor->action_id!=start.action_id)return common_failure("TacticLessonParticipantUnavailable",*id);auto at=c.resolved_location(*id);if(!at.ok)return {false,{},at.error};const auto* place=std::get_if<SettlementLocation>(&at.value);if(!place||place->place_id!=start.agreement.place_id)return common_failure("TacticLessonParticipantNotPresent",*id);}return common_success();}
Outcome<std::optional<FamilyDeathOrigin>> first_death(const CommonStore& c,const GrowthTacticLessonRuntimeAccess& access,const GrowthTacticLessonStart& start,const StableId& id){
    if(!access.deaths)return fail<std::optional<FamilyDeathOrigin>>(common_failure("TacticLessonDeathSourceRequired"));std::optional<FamilyDeathOrigin> first;
    for(const auto* actor:{&start.agreement.student_id,&start.agreement.teacher_id}){auto death=access.deaths(*actor);if(!death.ok)return death;const auto* person=c.actor(*actor);if(!person)return fail<std::optional<FamilyDeathOrigin>>(common_failure("TacticLessonParticipantMissing",*actor));if(!death.value){if(!person->alive)return fail<std::optional<FamilyDeathOrigin>>(common_failure("TacticLessonDeathSourceUnknown",*actor));continue;}const auto& source=*death.value;const auto* header=c.state().facts.find(source.casualty_fact_id);if(person->alive||source.actor_id!=*actor||source.tick<start.agreement.tick||source.tick>c.tick()||!header||header->id!=source.casualty_fact_id||header->kind!="military_casualties"||header->domain!="military"||position(c,source.casualty_fact_id)<=position(c,id))return fail<std::optional<FamilyDeathOrigin>>(common_failure("TacticLessonDeathSourceMismatch",*actor));if(!first||position(c,source.casualty_fact_id)<position(c,first->casualty_fact_id))first=source;}
    return {true,first,{}};
}
// 先完整生成释放recipe，之后真实头与payload同候选落账；不自行开嵌套Common保存点。
Outcome<GrowthTacticLessonEffect> close(CommonStore& c,GrowthTacticLessonState& state,const StableId& id,const StableId& reason,const StableId& cause){auto original=active(c,state,id);if(!original.ok)return {false,{},original.error};const auto start=*original.value;auto release=release_growth_tactic_lesson_recipe(c,state,id);if(!release.ok)return {false,{},release.error};auto source=c.next_id("tactic_lesson");if(!source.ok)return {false,{},source.error};auto applied=c.apply_resources(release.value.recipe);if(!applied.ok)return fail<GrowthTacticLessonEffect>(applied);GrowthTacticLessonClosure end;end.started_fact_id=id;end.action_id=start.action_id;end.reason=reason;end.cause_fact_id=cause;end.tick=c.tick();end.provided_half_days=release.value.provided_half_days;end.fee_paid=release.value.fee_paid;end.fee_released=release.value.fee_remaining;if(!state.closures.insert(source.value,end))return fail<GrowthTacticLessonEffect>(common_failure("DuplicateTacticLessonClosure"));applied=c.append_fact({source.value,end.kind,"growth_tactic_lessons"});if(!applied.ok)return fail<GrowthTacticLessonEffect>(applied);applied=validate_growth_tactic_lesson_shape(state);if(!applied.ok)return fail<GrowthTacticLessonEffect>(applied);return {true,{start.action_id,id,source.value,reason,true,reason=="completed",end.provided_half_days,end.fee_paid,end.fee_released},{}};}
}
Outcome<StableId> start_growth_tactic_lesson_in_candidate(CommonStore& c,GrowthTacticLessonState& state,const InteractionState& meeting,const InteractionCatalog& talks,const InteractionAccess& interaction,const GrowthTacticLessonCatalog& catalog,const GrowthTacticLessonSourceAccess& access,const GrowthTacticLessonQuote& quote){
    auto checked=validate_growth_tactic_lesson_shape(state);if(!checked.ok)return fail<StableId>(checked);checked=revalidate_growth_tactic_lesson(c,meeting,talks,interaction,catalog,access,quote);if(!checked.ok)return fail<StableId>(checked);for(const auto& row:state.starts.rows())if(row.second.agreement.session_id==quote.agreement.session_id&&row.second.agreement.definition_id==quote.agreement.definition_id&&row.second.agreement.student_id==quote.agreement.student_id)return fail<StableId>(common_failure("TacticLessonOfferConsumed"));
    auto action_id=c.next_id("action");if(!action_id.ok)return action_id;auto source=c.next_id("tactic_lesson");if(!source.ok)return source;GrowthTacticLessonStart start;start.action_id=action_id.value;start.agreement=quote.agreement;const auto& s=start.agreement;ActionCoreView action{action_id.value,"tactic_lesson",s.student_id,{s.student_id,s.teacher_id},c.tick(),s.duration};checked=adopt_started_action_in_candidate(c,action);if(!checked.ok)return fail<StableId>(checked);
    if(!state.starts.insert(source.value,start))return fail<StableId>(common_failure("DuplicateTacticLessonStart"));checked=c.append_fact({source.value,start.kind,"growth_tactic_lessons"});if(!checked.ok)return fail<StableId>(checked);auto recipe=reserve_growth_tactic_lesson_recipe(c,state,source.value);if(!recipe.ok)return {false,{},recipe.error};checked=c.apply_resources(recipe.value);if(!checked.ok)return fail<StableId>(checked);return source;
}
Outcome<GrowthTacticLessonEffect> cancel_growth_tactic_lesson_in_candidate(CommonStore& c,GrowthTacticLessonState& state,const StableId& actor,const StableId& id){auto original=active(c,state,id);if(!original.ok)return {false,{},original.error};const auto& start=*original.value;const auto* person=c.actor(actor);const auto* action=c.action(start.action_id);if(actor!=c.state().metadata.player_actor_id||actor!=start.agreement.student_id||!person||!person->alive||person->action_id!=start.action_id||action->remaining_ticks!=start.agreement.duration-periods(state,id))return fail<GrowthTacticLessonEffect>(common_failure("TacticLessonStudentCancellationRequired"));return close(c,state,id,"student_cancelled",{});}
Outcome<GrowthTacticLessonEffect> close_growth_tactic_lesson_after_death_in_candidate(CommonStore& c,GrowthTacticLessonState& state,const GrowthTacticLessonRuntimeAccess& access,const StableId& id){auto original=active(c,state,id);if(!original.ok)return {false,{},original.error};if(c.action(original.value->action_id)->remaining_ticks!=original.value->agreement.duration-periods(state,id))return fail<GrowthTacticLessonEffect>(common_failure("TacticLessonStableActionMismatch"));auto death=first_death(c,access,*original.value,id);if(!death.ok)return {false,{},death.error};if(!death.value)return fail<GrowthTacticLessonEffect>(common_failure("TacticLessonActualDeathRequired"));return close(c,state,id,death.value->actor_id==original.value->agreement.student_id?"student_dead":"teacher_dead",death.value->casualty_fact_id);}
Outcome<GrowthTacticLessonEffect> finish_growth_tactic_lesson_half_day_in_candidate(CommonStore& c,GrowthTacticLessonState& state,const GrowthTacticLessonRuntimeAccess& access,const StableId& id,const DynamicStepInput& step){
    if(step.from_tick<0||step.from_tick>=2147483647||step.to_tick!=step.from_tick+1||step.to_tick!=c.tick())return fail<GrowthTacticLessonEffect>(common_failure("TacticLessonCommittedHalfDayRequired"));auto original=active(c,state,id);if(!original.ok)return {false,{},original.error};const auto start=*original.value;const auto n=periods(state,id);const auto* action=c.action(start.action_id);if(n>=start.agreement.duration||c.tick()-start.agreement.tick!=n+1||action->remaining_ticks!=start.agreement.duration-n-1)return fail<GrowthTacticLessonEffect>(common_failure("TacticLessonHalfDayActionMismatch"));
    auto death=first_death(c,access,start,id);if(!death.ok)return {false,{},death.error};if(death.value)return close(c,state,id,death.value->actor_id==start.agreement.student_id?"student_dead":"teacher_dead",death.value->casualty_fact_id);
    if(access.interruption){auto interrupted=access.interruption(start,id);if(!interrupted.ok)return {false,{},interrupted.error};if(interrupted.value){const auto& p=*interrupted.value;const auto* header=c.state().facts.find(p.cause_fact_id);if((p.actor_id!=start.agreement.student_id&&p.actor_id!=start.agreement.teacher_id)||p.tick<start.agreement.tick||p.tick>c.tick()||!header||header->id!=p.cause_fact_id||!((header->kind=="military_casualties"&&header->domain=="military"&&p.cause_fact_id.rfind("military:",0)==0)||(header->kind=="military_contact"&&header->domain=="military"&&p.cause_fact_id.rfind("contact:",0)==0)||(header->kind=="naval_contact"&&header->domain=="military_naval"&&p.cause_fact_id.rfind("naval_contact:",0)==0))||position(c,p.cause_fact_id)<=position(c,id))return fail<GrowthTacticLessonEffect>(common_failure("TacticLessonInterruptionSourceMismatch"));return close(c,state,id,p.actor_id==start.agreement.student_id?"student_unavailable":"teacher_unavailable",p.cause_fact_id);}}
    auto checked=present(c,start);if(!checked.ok)return fail<GrowthTacticLessonEffect>(checked);auto payment=pay_growth_tactic_lesson_recipe(c,state,id);if(!payment.ok)return {false,{},payment.error};auto source=c.next_id("tactic_lesson");if(!source.ok)return {false,{},source.error};checked=c.apply_resources(payment.value.recipe);if(!checked.ok)return fail<GrowthTacticLessonEffect>(checked);GrowthTacticLessonCredit credit;credit.started_fact_id=id;credit.action_id=start.action_id;credit.tick=c.tick();credit.ordinal=payment.value.provided_half_days;credit.fee_paid=payment.value.fee_paid;if(!state.credits.insert(source.value,credit))return fail<GrowthTacticLessonEffect>(common_failure("DuplicateTacticLessonCredit"));checked=c.append_fact({source.value,credit.kind,"growth_tactic_lessons"});if(!checked.ok)return fail<GrowthTacticLessonEffect>(checked);
    if(credit.ordinal==start.agreement.duration)return close(c,state,id,"completed",{});return {true,{start.action_id,id,source.value,"provided",false,false,credit.ordinal,credit.fee_paid,0},{}};
}
}
